import { useEvent } from "../useEvent/index.mjs";
import { useState } from "react";
//#region src/useBoolean/index.ts
const useBoolean = (initialValue = false) => {
	const [value, setValue] = useState(initialValue);
	const setTrue = useEvent(() => {
		setValue(true);
	});
	const setFalse = useEvent(() => {
		setValue(false);
	});
	const toggle = useEvent(() => {
		setValue((prev) => !prev);
	});
	return {
		value,
		setValue: useEvent((newValue) => {
			setValue(newValue);
		}),
		setTrue,
		setFalse,
		toggle
	};
};
//#endregion
export { useBoolean };
